function toast(message: string) { const el=$('#toast'),feedback=document.querySelector<HTMLElement>('#dialog-feedback');el.textContent=message;el.hidden=dialog.open;if(dialog.open&&feedback){feedback.textContent=message;feedback.hidden=false;}clearTimeout((toast as unknown as {timer:number}).timer);(toast as unknown as {timer:number}).timer=window.setTimeout(()=>{el.hidden=true;if(feedback)feedback.hidden=true;},4500); }
